15	/**
16	 * Renders in-page anchors (footnote references/backrefs, heading links — any `href="#…"`).
17	 *
18	 * When the target lives in a fully-rendered memo (detail, share, preview, expanded feed card),
19	 * we scroll to it within that memo's own container — scoped so duplicate footnote ids across a
20	 * feed can't send us to the wrong memo. When the memo is a collapsed feed card the footnote is
21	 * below the fold, so we fall back to navigating to the memo detail page (with the hash), where
22	 * MemoDetail scrolls the target into view.
23	 */
24	export const AnchorLink = ({ href, memoName, compact, children, className, node: _node, ...props }: AnchorLinkProps) => {
25	  const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
26	    if (compact) return; // Let the link navigate to the detail page.
27	    const id = decodeURIComponent(href.slice(1));
28	    if (!id) return;
29	    // Scope the lookup to this memo's own container so duplicate footnote ids elsewhere in a feed
30	    // can't steal the scroll.
31	    const root = event.currentTarget.closest("[data-memo-content]");
32	    const target = root?.querySelector(`#${CSS.escape(id)}`);
33	    if (target) {
34	      event.preventDefault();
35	      target.scrollIntoView({ behavior: "smooth", block: "center" });
36	    }
37	  };
38	
39	  const classes = cn(markdownStyles.link, className);
40	
41	  if (memoName) {
42	    return (
43	      <Link to={`/${memoName}${href}`} onClick={handleClick} className={classes} {...props}>
44	        {children}
45	      </Link>
46	    );
47	  }
48	
49	  return (
50	    <a href={href} onClick={handleClick} className={classes} {...props}>
51	      {children}
52	    </a>
53	  );
54	};
